package app.gendragoon.cloudssd.mobile;
import android.content.Context;
import java.io.*;
import java.nio.file.*;
import java.util.Arrays;
import org.json.JSONObject;

final class DeviceVault {
    static File directory(Context context,String receiver)throws Exception{if(!receiver.matches("[a-f0-9]{64}"))throw new IOException("Invalid account vault.");File dir=new File(context.getFilesDir().getCanonicalFile(),"redx-vault/"+receiver);if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("Private vault directory unavailable.");if(!dir.getCanonicalFile().equals(dir.getAbsoluteFile()))throw new IOException("Linked private vault directory rejected.");android.system.Os.chmod(dir.getPath(),0700);return dir;}
    static File keymap(Context context,String receiver)throws Exception{return new File(directory(context,receiver),"private.keymap");}
    static String secret(Context context,String receiver)throws Exception{String value=SecurePrefs.get(context,"vault:"+receiver);File file=keymap(context,receiver);if(value==null||!value.matches("[A-Za-z0-9_-]{32,128}")||!file.isFile()||Files.isSymbolicLink(file.toPath()))throw new IOException("Import your encrypted portable vault before accessing encrypted files. Account sign-in cannot recover a lost private keymap.");return value;}
    static synchronized void install(Context context,PortableVault.Keys keys)throws Exception{PortableVault.keymap(keys.keymap);File target=keymap(context,keys.receiver);String prior=SecurePrefs.get(context,"vault:"+keys.receiver);if(prior!=null&&!prior.equals(keys.secret)||target.exists()&&!Arrays.equals(Files.readAllBytes(target.toPath()),keys.keymap))throw new IOException("A different vault already exists on this device. It was retained; no keys were overwritten.");if(!target.exists()){File temp=new File(target.getParentFile(),".import-"+java.util.UUID.randomUUID());try{try(FileOutputStream output=new FileOutputStream(temp)){output.write(keys.keymap);output.getFD().sync();}android.system.Os.chmod(temp.getPath(),0600);CryptoRuntime.verifyKeymap(context,temp,keys.secret);SecurePrefs.put(context,"vault:"+keys.receiver,keys.secret);Files.move(temp.toPath(),target.toPath(),StandardCopyOption.ATOMIC_MOVE);}finally{temp.delete();}}else{CryptoRuntime.verifyKeymap(context,target,keys.secret);SecurePrefs.put(context,"vault:"+keys.receiver,keys.secret);}}
    static synchronized void initialize(Context context,String receiver)throws Exception{File target=keymap(context,receiver);if(target.exists()||SecurePrefs.get(context,"vault:"+receiver)!=null)throw new IOException("An existing private vault was retained.");String secret=RedXSession.random();File temp=new File(target.getParentFile(),".new-"+java.util.UUID.randomUUID());try{CryptoRuntime.module(context).callAttr("initialize_vault",temp.getCanonicalPath(),secret);install(context,new PortableVault.Keys(receiver,secret,Files.readAllBytes(temp.toPath())));}finally{temp.delete();new File(temp.getPath()+".gen").delete();}}
    static JSONObject configuration(Context context,String subject,String workspace)throws Exception{JSONObject profile=RedXSession.profile(context);if(profile==null||!subject.equals(profile.optString("subject")))throw new IOException("The connected account changed.");String receiver=RedXSession.receiver(subject);return new JSONObject().put("provider","redxai").put("cloudApi",CloudApi.ORIGIN).put("workspaceId",workspace).put("receiverId",receiver).put("bearerToken",RedXSession.access(context,subject,false)).put("storageSecret",secret(context,receiver)).put("keymapPath",keymap(context,receiver).getCanonicalPath()).put("constrained",false);}
}
